import { HorizontalRuleNode } from "@lexical/react/LexicalHorizontalRuleNode.js";
const LexicalThematicBreakVisitor = {
  testLexicalNode: (node) => node instanceof HorizontalRuleNode,
  visitLexicalNode({ actions }) {
    actions.addAndStepInto("thematicBreak");
  }
};
export {
  LexicalThematicBreakVisitor
};
